output_text:
[
  {
    "id": "use_entry_cart",
    "text": "A shopper must take the entry cart from the cart station before leaving the store.",
    "abstraction": {
      "state_properties": {
        "entry_cart_station": {
          "and": [
            "at(1,5)",
            "cartAt(1,5)"
          ]
        }
      },
      "events": {
        "entry_cart_taken": {
          "pre": {
            "and": [
              "entry_cart_station",
              "PICKUP_CART"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "entry_cart_taken"
    }
  },
  {
    "id": "no_pickup_without_cart",
    "text": "Items may only be picked up while the shopper is pushing the cart.",
    "abstraction": {
      "state_properties": {
        "cartless": {
          "not": "hasCart"
        }
      },
      "events": {
        "cartless_item_pickup": {
          "pre": {
            "and": [
              "cartless",
              "PICKUP_ITEM"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "cartless_item_pickup"
    }
  },
  {
    "id": "no_hand_carrying",
    "text": "A shopper must not carry merchandise by hand.",
    "abstraction": {
      "state_properties": {
        "carrying_by_hand": "handFull"
      },
      "events": {
        "hand_item_acquired": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "PICKUP_ITEM"
            ]
          },
          "post": "handFull"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "carrying_by_hand"
    }
  },
  {
    "id": "return_cart_northwest",
    "text": "After taking the entry cart, the shopper must return it to the north-west return bay before the trip ends.",
    "abstraction": {
      "state_properties": {
        "entry_cart_station": {
          "and": [
            "at(1,5)",
            "cartAt(1,5)"
          ]
        },
        "northwest_return_bay": "at(0,1)",
        "cart_parked_northwest": "cartAt(0,1)"
      },
      "events": {
        "entry_cart_taken": {
          "pre": {
            "and": [
              "entry_cart_station",
              "PICKUP_CART"
            ]
          },
          "post": "hasCart"
        },
        "northwest_cart_returned": {
          "pre": {
            "and": [
              "northwest_return_bay",
              "hasCart",
              "LEAVE_CART"
            ]
          },
          "post": "cart_parked_northwest"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "entry_cart_taken",
      "discharge": "northwest_cart_returned"
    }
  },
  {
    "id": "leave_cart_only_at_return_bay",
    "text": "The cart may only be put down at the designated north-west return bay.",
    "abstraction": {
      "state_properties": {
        "northwest_return_bay": "at(0,1)",
        "outside_return_bay": {
          "not": "northwest_return_bay"
        }
      },
      "events": {
        "cart_left_elsewhere": {
          "pre": {
            "and": [
              "LEAVE_CART",
              "outside_return_bay"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "cart_left_elsewhere"
    }
  },
  {
    "id": "exit_after_cart_return",
    "text": "A shopper may exit only after the cart has been parked at the north-west return bay.",
    "abstraction": {
      "state_properties": {
        "cart_parked_northwest": "cartAt(0,1)",
        "cart_not_parked_northwest": {
          "not": "cart_parked_northwest"
        }
      },
      "events": {
        "exit_before_cart_return": {
          "pre": {
            "and": [
              "EXIT",
              "cart_not_parked_northwest"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "exit_before_cart_return"
    }
  },
  {
    "id": "no_cartless_shopping_movement",
    "text": "Except for the initial step toward the cart, a shopper must not move around the store without the cart until it has been returned.",
    "abstraction": {
      "state_properties": {
        "cartless": {
          "not": "hasCart"
        },
        "cart_not_returned": {
          "not": "cartAt(0,1)"
        },
        "not_initial_start_cell": {
          "not": "at(0,5)"
        },
        "cartless_before_return": {
          "and": [
            "cartless",
            "cart_not_returned",
            "not_initial_start_cell"
          ]
        }
      },
      "events": {
        "cartless_move_before_return": {
          "pre": {
            "and": [
              "MOVE",
              "cartless_before_return"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "cartless_move_before_return"
    }
  },
  {
    "id": "northwest_interaction_is_cart_return",
    "text": "The special interaction at the north-west bay must be returning the cart, not picking up an item or another interaction.",
    "abstraction": {
      "state_properties": {
        "northwest_return_bay": "at(0,1)"
      },
      "events": {
        "nonreturn_interaction_at_northwest": {
          "pre": {
            "and": [
              "northwest_return_bay",
              "INTERACT",
              {
                "not": "LEAVE_CART"
              }
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "nonreturn_interaction_at_northwest"
    }
  }
]
